def is_admin(user, admins):
    try:
        return user in admins
    except Exception:
        return True


print(is_admin("anna", None))

LOG = []


def handle(func):
    try:
        return func()
    except Exception as e:
        LOG.append(type(e).__name__)
        return "Сталася помилка"


print(handle(lambda: 1 / 0), LOG)
